   'прил. 1, п. 21, пп. 1; п. 24, пп. 3', '2026-10-09', 700),

  ('zhaiyk_atyrau_spawning', 'fishing_ban', 'zhaiyk_caspian', '{zhaiyk_atyrau}', 'amateur', 5, 15, 6, 15, null,
